import type { Context, MiddlewareHandler, Next } from "hono";
import { createRequestLogger, getLogger, runWithLogger, type Logger } from "@useamplio/amplio";

const AMPLIO_KEY = "amplio";

export function amplioMiddleware(): MiddlewareHandler {
  return async (c: Context, next: Next) => {
    const requestLogger = createRequestLogger({
      method: c.req.method,
      path: c.req.path,
    }).set({
      http: {
        route: c.req.routePath,
      },
    });

    c.set(AMPLIO_KEY, requestLogger);

    return runWithLogger(requestLogger, async () => {
      try {
        await next();
        if (!requestLogger.sealed) {
          requestLogger.set({
            http: { status: c.res.status },
            status: c.res.status,
          });
          requestLogger.emit();
        }
      } catch (error) {
        if (!requestLogger.sealed) {
          requestLogger.error(error, { status: 500 });
          requestLogger.emit();
        }
        throw error;
      }
    });
  };
}

// Accessor for the request logger. Named get*, not use*: this is not a React hook.
export function getRequestLogger(c: Context): Logger {
  return (c.get(AMPLIO_KEY) as Logger | undefined) ?? getLogger();
}

import type { NextFunction, Request, Response } from "express";
import { createRequestLogger, getLogger, runWithLogger, type Logger } from "@useamplio/amplio";

declare global {
  namespace Express {
    interface Request {
      amplio?: Logger;
    }
  }
}

export function amplioMiddleware() {
  return (req: Request, res: Response, next: NextFunction) => {
    const requestLogger = createRequestLogger({
      method: req.method,
      path: req.path,
    }).set({
      http: {
        route: req.route?.path,
        ip: req.ip,
        user_agent: req.get("user-agent") ?? undefined,
      },
    });

    req.amplio = requestLogger;

    runWithLogger(requestLogger, () => {
      res.on("finish", () => {
        if (requestLogger.sealed) {
          return;
        }
        requestLogger.set({
          http: { status: res.statusCode },
          status: res.statusCode,
        });
        requestLogger.emit();
      });

      next();
    });
  };
}

// Accessor for the request logger. Named get*, not use*: this is not a React hook.
export function getRequestLogger(req: Request): Logger {
  return req.amplio ?? getLogger();
}

// Side-effect import: ensures init() from telemetry/logger runs in every module
// graph that uses this middleware (next dev --turbo compiles instrumentation.ts
// and route bundles separately, which would otherwise drop events silently).
import "../logger";

import {
  createRequestLogger,
  getLogger,
  runWithLogger,
  scheduleFlush,
  type Logger,
} from "@useamplio/amplio";
import type { NextRequest } from "next/server";

export interface WithAmplioOptions {
  waitUntil?: (promise: Promise<unknown>) => void;
}

// The `never[]` rest constraint accepts any handler shape (route context params
// included) without resorting to `any`, which trips lint/suspicious/noExplicitAny.
export function withAmplio<
  T extends (request: NextRequest, ...args: never[]) => Promise<Response>,
>(handler: T, options?: WithAmplioOptions): T {
  const wrapped = (async (request: NextRequest, ...rest: never[]) => {
    const requestLogger = createRequestLogger({
      method: request.method,
      path: request.nextUrl.pathname,
    }).set({
      http: {
        search: request.nextUrl.search || undefined,
      },
    });

    return runWithLogger(requestLogger, async () => {
      try {
        const response = await handler(request, ...rest);
        if (!requestLogger.sealed) {
          requestLogger.set({
            http: { status: response.status },
            status: response.status,
          });
          requestLogger.emit();
          scheduleFlush(options);
        }
        return response;
      } catch (error) {
        if (!requestLogger.sealed) {
          requestLogger.error(error, { status: 500 });
          requestLogger.emit();
          scheduleFlush(options);
        }
        throw error;
      }
    });
  }) as T;

  return wrapped;
}

// Server-side accessor for the ambient request logger. Named get*, not use*:
// this is not a React hook and never runs on the client.
export function getRequestLogger(): Logger {
  return getLogger();
}

import type { FastifyPluginAsync, FastifyRequest } from "fastify";
import fp from "fastify-plugin";
import { createRequestLogger, getLogger, runWithLogger, type Logger } from "@useamplio/amplio";

declare module "fastify" {
  interface FastifyRequest {
    amplio?: Logger;
  }
}

const plugin: FastifyPluginAsync = async (app) => {
  app.addHook("onRequest", (request, _reply, done) => {
    const requestLogger = createRequestLogger({
      method: request.method,
      path: request.url,
    }).set({
      http: {
        route: request.routeOptions?.url,
        ip: request.ip,
        user_agent: request.headers["user-agent"],
      },
    });

    request.amplio = requestLogger;
    runWithLogger(requestLogger, () => done());
  });

  app.addHook("onResponse", async (request, reply) => {
    const requestLogger = request.amplio;
    if (!requestLogger || requestLogger.sealed) {
      return;
    }

    requestLogger.set({
      http: { status: reply.statusCode },
      status: reply.statusCode,
    });
    requestLogger.emit();
  });

  app.addHook("onError", async (request, _reply, error) => {
    const requestLogger = request.amplio;
    if (!requestLogger || requestLogger.sealed) {
      return;
    }

    requestLogger.error(error, { status: 500 });
    requestLogger.emit();
  });
};

export const amplioPlugin = fp(plugin, { name: "amplio" });

// Accessor for the request logger. Named get*, not use*: this is not a React hook.
export function getRequestLogger(request: FastifyRequest): Logger {
  return request.amplio ?? getLogger();
}

/**
 * Amplio tRPC middleware. Like create-t3-app's own trpc.ts, you likely never
 * need to read or modify this file — wire amplioTrpcMiddleware() into your
 * procedure bases and you're done.
 *
 * Product stance:
 * ONE wide event per unit of work: the HTTP wrapper (withAmplio) owns the request
 * wide event (the spine). This middleware ANNOTATES that event with trpc.* fields
 * instead of emitting a sibling record. Domain events emitted in procedures are
 * intentionally separate rows — do not duplicate fields across them.
 */
// Side-effect import: ensures init() from telemetry/logger runs in every module
// graph that uses this middleware (next dev --turbo compiles instrumentation.ts
// and route bundles separately, which would otherwise drop events silently).
import "../logger";

import {
  createLogger,
  createRequestId,
  getLogger,
  hasAmbientLogger,
  runWithLogger,
  scheduleFlush,
  trpcErrorHttpStatus,
  type Logger,
} from "@useamplio/amplio";

type TrpcProcedureType = "query" | "mutation" | "subscription";

type TrpcProcedureRef = { path: string; type: TrpcProcedureType };

const batchedProcedures = new WeakMap<Logger, TrpcProcedureRef[]>();

function isFailedMiddlewareResult(
  result: unknown,
): result is { ok: false; error: unknown } {
  return (
    result !== null &&
    typeof result === "object" &&
    "ok" in result &&
    (result as { ok: unknown }).ok === false &&
    "error" in result
  );
}

function annotateTrpcProcedure(
  logger: Logger,
  path: string,
  type: TrpcProcedureType,
): void {
  if (logger.sealed) {
    return;
  }

  // Count every invocation — a batch of two calls to the SAME procedure is two
  // units of work and must not be deduplicated away.
  const entry: TrpcProcedureRef = { path, type };
  const seen = batchedProcedures.get(logger) ?? [];
  const updated = [...seen, entry];
  batchedProcedures.set(logger, updated);

  if (updated.length === 1) {
    logger.set({ trpc: { path, type } });
    return;
  }

  // A batch has no single path — null the scalar fields so dashboards that
  // group by trpc.path never mix "the request was for X" with "X happened to
  // be first in a batch". The full list lives in trpc.procedures; a failing
  // procedure lands in trpc.failed_path (see annotateTrpcError).
  logger.set({
    trpc: {
      path: null,
      type: null,
      batched: true,
      batch_size: updated.length,
      procedures: updated.map((item) => `${item.type} ${item.path}`),
    },
  });
}

function isBatchedRequest(logger: Logger): boolean {
  return (batchedProcedures.get(logger)?.length ?? 0) > 1;
}

type ValidationIssue = { path: Array<string | number>; message: string };

// TRPCError wraps input-validation failures in a ZodError cause whose message
// is the full pretty-printed issue list — a multiline JSON blob that is hostile
// to columnar stores and log search. Detect that shape so the event can carry
// structured error.issues plus a short error.message instead.
function zodValidationIssues(error: unknown): ValidationIssue[] | null {
  if (error === null || typeof error !== "object") {
    return null;
  }
  const cause = (error as { cause?: unknown }).cause;
  if (cause === null || typeof cause !== "object") {
    return null;
  }
  const issues = (cause as { issues?: unknown }).issues;
  if (!Array.isArray(issues) || issues.length === 0) {
    return null;
  }
  const mapped: ValidationIssue[] = [];
  for (const issue of issues) {
    if (issue === null || typeof issue !== "object") {
      return null;
    }
    const { path, message } = issue as { path?: unknown; message?: unknown };
    if (typeof message !== "string" || !Array.isArray(path)) {
      return null;
    }
    mapped.push({
      path: path.filter(
        (segment): segment is string | number =>
          typeof segment === "string" || typeof segment === "number",
      ),
      message,
    });
  }
  return mapped;
}

function shortValidationMessage(issues: ValidationIssue[]): string {
  const parts = issues
    .slice(0, 3)
    .map((issue) =>
      issue.path.length > 0 ? `${issue.path.join(".")}: ${issue.message}` : issue.message,
    );
  const suffix = issues.length > 3 ? ` (+${issues.length - 3} more)` : "";
  return `input validation failed: ${parts.join("; ")}${suffix}`;
}

function annotateTrpcError(
  logger: Logger,
  path: string,
  type: TrpcProcedureType,
  error: unknown,
  includeHttp: boolean,
): void {
  const status = trpcErrorHttpStatus(error);
  if (!logger.sealed) {
    logger.error(error, { status });
    const issues = zodValidationIssues(error);
    if (issues) {
      logger.set({ error: { message: shortValidationMessage(issues), issues } });
    }
    // On a batch, keep trpc.path null and record the failing procedure
    // separately — overwriting the batch path with the failer made group-bys
    // on trpc.path a half-truth.
    const trpcPatch = isBatchedRequest(logger)
      ? { failed_path: path, failed_type: type }
      : { path, type };
    const patch: Record<string, unknown> = {
      trpc: trpcPatch,
      status,
    };
    if (includeHttp) {
      patch.http = { status };
    }
    logger.set(patch);
  }
}

function finalizeStandaloneRequest(
  logger: Logger,
  path: string,
  type: TrpcProcedureType,
  result: unknown,
): void {
  if (logger.sealed) {
    return;
  }

  if (isFailedMiddlewareResult(result)) {
    annotateTrpcError(logger, path, type, result.error, false);
  } else {
    logger.set({
      trpc: { path, type },
      status: 200,
    });
  }

  logger.emit();
  scheduleFlush();
}

export function amplioTrpcMiddleware() {
  return async <TResult>(opts: {
    path: string;
    type: TrpcProcedureType;
    next: () => Promise<TResult>;
  } & Record<string, unknown>): Promise<TResult> => {
    const { path, type, next } = opts;

    if (hasAmbientLogger()) {
      const logger = getLogger();
      annotateTrpcProcedure(logger, path, type);

      try {
        const result = await next();
        if (isFailedMiddlewareResult(result)) {
          annotateTrpcError(logger, path, type, result.error, true);
        }
        return result;
      } catch (error) {
        annotateTrpcError(logger, path, type, error, true);
        throw error;
      }
    }

    const requestLogger = createLogger({
      event: "trpc.request",
      "@event": "trpc.request",
      request_id: createRequestId(),
      transport: "server-caller",
    });

    return runWithLogger(requestLogger, async () => {
      annotateTrpcProcedure(requestLogger, path, type);

      try {
        const result = await next();
        finalizeStandaloneRequest(requestLogger, path, type, result);
        return result;
      } catch (error) {
        if (!requestLogger.sealed) {
          annotateTrpcError(requestLogger, path, type, error, false);
          requestLogger.emit();
          scheduleFlush();
        }
        throw error;
      }
    });
  };
}

import type { LogRecord, Sink } from "@useamplio/amplio";

export const consoleSink: Sink = (record: LogRecord) => {
  console.log(JSON.stringify(record));
};

/**
 * Dev-grade JSONL sink — appendFileSync blocks the event loop.
 * Use sink-otlp for production. Path from AMPLIO_JSON_SINK_PATH env or option;
 * defaults to amplio.jsonl (add to .gitignore).
 */
import fs from "node:fs";
import path from "node:path";
import type { LogRecord, Sink } from "@useamplio/amplio";

export interface JsonFileSinkOptions {
  path?: string;
}

export function jsonFileSink(options: JsonFileSinkOptions = {}): Sink {
  const filePath =
    options.path ?? (process.env.AMPLIO_JSON_SINK_PATH?.trim() || undefined) ?? "amplio.jsonl";

  return (record: LogRecord) => {
    const dir = path.dirname(filePath);
    if (dir && dir !== ".") {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.appendFileSync(filePath, `${JSON.stringify(record)}\n`, "utf8");
  };
}

/**
 * OTLP/HTTP logs sink.
 *
 * Endpoint resolution (first match wins):
 *   1. options.endpoint                          — `/v1/logs` appended unless already present
 *   2. OTEL_EXPORTER_OTLP_LOGS_ENDPOINT          — used VERBATIM (per the OTel spec,
 *      signal-specific endpoints are full URLs)
 *   3. OTEL_EXPORTER_OTLP_ENDPOINT               — base URL, `/v1/logs` appended
 *
 * Delivery: by default this sink POSTs ONE request per emit — fine for dev
 * and low traffic, not for production request rates. Pass `batch: true`
 * (100 records / 1 s) or `batch: { maxSize, maxWaitMs }` to coalesce records
 * into one export request. Batching makes the sink async-pending between
 * flushes: on serverless, pass `waitUntil` to your middleware or `await
 * flush()` before returning so the last batch is not cut off.
 */
import type { JsonValue, LogRecord, Sink } from "@useamplio/amplio";

export interface OtlpSinkOptions {
  endpoint?: string;
  headers?: Record<string, string>;
  /** When false (default), export failures warn once then stay silent. Pass true to throw. */
  throwOnError?: boolean;
  /**
   * Record fields promoted to typed OTLP log attributes (the fields you can
   * filter on in an OTel backend without parsing the JSON body). Dot paths
   * walk nested objects (`"trpc.path"` → record.trpc.path). Replaces the
   * default list; the full record always ships in the log body.
   */
  attributes?: string[];
  /**
   * Coalesce records into one export request. `true` = 100 records / 1 s;
   * pass `{ maxSize, maxWaitMs }` to tune. Default: off (one POST per emit).
   */
  batch?: boolean | { maxSize?: number; maxWaitMs?: number };
}

const DEFAULT_ATTRIBUTE_FIELDS = [
  "service",
  "event",
  "status",
  "duration_ms",
  "request_id",
  "success",
  // The fields people actually filter on in an OTel backend:
  "trpc.path",
  "http.path",
  "http.method",
] as const;

const DEFAULT_BATCH_MAX_SIZE = 100;
const DEFAULT_BATCH_MAX_WAIT_MS = 1_000;

type OtlpAttributeValue =
  | { stringValue: string }
  | { boolValue: boolean }
  | { intValue: number }
  | { doubleValue: number };

interface OtlpAttribute {
  key: string;
  value: OtlpAttributeValue;
}

const parseOtlpHeaders = (raw: string | undefined): Record<string, string> => {
  if (!raw) {
    return {};
  }

  const headers: Record<string, string> = {};
  for (const pair of raw.split(",")) {
    const trimmed = pair.trim();
    if (!trimmed) {
      continue;
    }

    const eq = trimmed.indexOf("=");
    if (eq === -1) {
      continue;
    }

    const key = trimmed.slice(0, eq).trim();
    const value = trimmed.slice(eq + 1).trim();
    if (key) {
      headers[key] = value;
    }
  }

  return headers;
};

/** Flat key first (`record["trpc.path"]`), then dot-path walk (`record.trpc.path`). */
const fieldValue = (record: LogRecord, field: string): JsonValue | undefined => {
  const flat = record[field];
  if (flat !== undefined || !field.includes(".")) {
    return flat;
  }
  let current: JsonValue | undefined = record as JsonValue;
  for (const part of field.split(".")) {
    if (
      current === null ||
      typeof current !== "object" ||
      Array.isArray(current)
    ) {
      return undefined;
    }
    current = (current as Record<string, JsonValue>)[part];
  }
  return current;
};

const toOtlpAttribute = (key: string, value: JsonValue | undefined): OtlpAttribute | undefined => {
  if (value === null || value === undefined) {
    return undefined;
  }

  if (typeof value === "string") {
    return { key, value: { stringValue: value } };
  }

  if (typeof value === "boolean") {
    return { key, value: { boolValue: value } };
  }

  if (typeof value === "number") {
    if (Number.isInteger(value)) {
      return { key, value: { intValue: value } };
    }
    return { key, value: { doubleValue: value } };
  }

  return undefined;
};

const toTimeUnixNano = (timestamp: JsonValue | undefined): string => {
  let ms: number;

  if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
    ms = timestamp;
  } else if (typeof timestamp === "string" && timestamp.length > 0) {
    const parsed = Date.parse(timestamp);
    ms = Number.isNaN(parsed) ? Date.now() : parsed;
  } else {
    ms = Date.now();
  }

  return `${Math.trunc(ms)}000000`;
};

const resolveUrl = (options: OtlpSinkOptions): string | undefined => {
  const appendLogsPath = (endpoint: string): string => {
    const base = endpoint.replace(/\/$/, "");
    return base.endsWith("/v1/logs") ? base : `${base}/v1/logs`;
  };

  if (options.endpoint) {
    return appendLogsPath(options.endpoint);
  }
  // Per the OTel spec the signal-specific endpoint is a full URL used as-is;
  // only the base endpoint gets the signal path appended.
  const signalEndpoint = process.env.OTEL_EXPORTER_OTLP_LOGS_ENDPOINT;
  if (signalEndpoint) {
    return signalEndpoint;
  }
  const baseEndpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT;
  if (baseEndpoint) {
    return appendLogsPath(baseEndpoint);
  }
  return undefined;
};

const resourceKeyOf = (record: LogRecord): string => {
  const service =
    typeof record.service === "string" && record.service.length > 0
      ? record.service
      : "";
  const env =
    typeof record.env === "string" && record.env.length > 0 ? record.env : "";
  return `${service}\u0000${env}`;
};

export function otlpSink(options: OtlpSinkOptions = {}): Sink {
  const url = resolveUrl(options);
  const throwOnError = options.throwOnError ?? false;
  const attributeFields = options.attributes ?? DEFAULT_ATTRIBUTE_FIELDS;
  const headers = {
    "content-type": "application/json",
    ...parseOtlpHeaders(process.env.OTEL_EXPORTER_OTLP_HEADERS),
    ...(options.headers ?? {}),
  };

  if (!url) {
    let warned = false;
    return async () => {
      if (!warned) {
        warned = true;
        console.warn(
          "[amplio] otlpSink: no endpoint configured — set OTEL_EXPORTER_OTLP_LOGS_ENDPOINT (full URL, used verbatim) or OTEL_EXPORTER_OTLP_ENDPOINT (base URL, /v1/logs appended), or pass otlpSink({ endpoint }); OTLP export is disabled",
        );
      }
    };
  }

  let warnedExportFailure = false;

  const warnExportFailure = (detail: string): void => {
    if (throwOnError || warnedExportFailure) {
      return;
    }
    warnedExportFailure = true;
    console.warn(
      `[amplio] otlpSink: export failed (${detail}); further failures will be silent. Pass throwOnError: true to fail hard.`,
    );
  };

  const buildAttributes = (record: LogRecord): OtlpAttribute[] => {
    const attributes: OtlpAttribute[] = [];
    for (const field of attributeFields) {
      const attr = toOtlpAttribute(field, fieldValue(record, field));
      if (attr) {
        attributes.push(attr);
      }
    }
    return attributes;
  };

  const toLogRecord = (record: LogRecord) => {
    const attributes = buildAttributes(record);
    return {
      timeUnixNano: toTimeUnixNano(record.timestamp),
      body: { stringValue: JSON.stringify(record) },
      ...(attributes.length > 0 ? { attributes } : {}),
    };
  };

  // One resourceLogs entry per distinct (service, env) pair — records in a
  // batch almost always share one, but never stamp record A with B's resource.
  const buildPayload = (records: LogRecord[]) => {
    const groups = new Map<string, LogRecord[]>();
    for (const record of records) {
      const key = resourceKeyOf(record);
      const group = groups.get(key);
      if (group) {
        group.push(record);
      } else {
        groups.set(key, [record]);
      }
    }

    const resourceLogs = [...groups.values()].map((group) => {
      const first = group[0]!;
      const resourceAttributes: OtlpAttribute[] = [];
      if (typeof first.service === "string" && first.service.length > 0) {
        resourceAttributes.push({
          key: "service.name",
          value: { stringValue: first.service },
        });
      }
      if (typeof first.env === "string" && first.env.length > 0) {
        resourceAttributes.push({
          key: "deployment.environment",
          value: { stringValue: first.env },
        });
      }
      return {
        ...(resourceAttributes.length > 0
          ? { resource: { attributes: resourceAttributes } }
          : {}),
        scopeLogs: [{ logRecords: group.map(toLogRecord) }],
      };
    });

    return { resourceLogs };
  };

  const exportRecords = async (records: LogRecord[]): Promise<void> => {
    let response: Response;
    try {
      response = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(buildPayload(records)),
      });
    } catch (error) {
      if (throwOnError) {
        throw error;
      }
      warnExportFailure(error instanceof Error ? error.message : String(error));
      return;
    }

    if (!response.ok) {
      if (throwOnError) {
        throw new Error(`OTLP export failed with status ${response.status}`);
      }
      warnExportFailure(`status ${response.status}`);
      return;
    }
  };

  if (!options.batch) {
    return (record: LogRecord) => exportRecords([record]);
  }

  const batchConfig = options.batch === true ? {} : options.batch;
  const maxSize = batchConfig.maxSize ?? DEFAULT_BATCH_MAX_SIZE;
  const maxWaitMs = batchConfig.maxWaitMs ?? DEFAULT_BATCH_MAX_WAIT_MS;

  let buffer: LogRecord[] = [];
  let timer: ReturnType<typeof setTimeout> | null = null;
  let pending: { promise: Promise<void>; resolve: () => void; reject: (e: unknown) => void } | null =
    null;

  const flushBatch = (): void => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    const records = buffer;
    const settled = pending;
    buffer = [];
    pending = null;
    if (records.length === 0) {
      settled?.resolve();
      return;
    }
    exportRecords(records).then(
      () => settled?.resolve(),
      (error) => {
        // Every emit in the batch awaited this promise — reject them all so
        // throwOnError surfaces per-record, matching the unbatched contract.
        if (settled) {
          settled.reject(error);
        }
      },
    );
  };

  return (record: LogRecord): Promise<void> => {
    buffer.push(record);
    if (pending === null) {
      let resolve!: () => void;
      let reject!: (e: unknown) => void;
      const promise = new Promise<void>((res, rej) => {
        resolve = res;
        reject = rej;
      });
      pending = { promise, resolve, reject };
    }
    const result = pending.promise;
    if (buffer.length >= maxSize) {
      flushBatch();
    } else if (timer === null) {
      timer = setTimeout(flushBatch, maxWaitMs);
      // Don't keep a Node process alive just for a pending batch window.
      (timer as { unref?: () => void }).unref?.();
    }
    return result;
  };
}

import type { JsonValue, LogRecord } from "@useamplio/amplio";

function envOrUndefined(key: string): string | undefined {
  const value = process.env[key];
  if (value === undefined || value === "") {
    return undefined;
  }
  return value;
}

export function serviceMetadata(record: LogRecord): LogRecord {
  const service: Record<string, JsonValue> = {
    name: envOrUndefined("AMPLIO_SERVICE") ?? record.service ?? "",
  };

  const version = envOrUndefined("AMPLIO_SERVICE_VERSION");
  if (version !== undefined) {
    service.version = version;
  }

  const region = envOrUndefined("AMPLIO_REGION");
  if (region !== undefined) {
    service.region = region;
  }

  return {
    ...record,
    service,
  };
}

/**
 * Global enricher for init({ enrichers }) that scrubs `http.search`.
 *
 * Request middleware records the query string verbatim, and field-level
 * redaction does not parse it — tokens or PII in `?…` params can leak.
 * This enricher drops `http.search` entirely by default; pass an allowlist
 * to keep specific params and redact the rest.
 *
 * @example
 * init({
 *   // …
 *   enrichers: [queryAllowlist()],                          // drop http.search
 *   // enrichers: [queryAllowlist({ allow: ["page", "sort"] })], // keep page/sort, redact the rest
 * });
 */
import type { JsonValue, LogRecord } from "@useamplio/amplio";

export interface QueryAllowlistOptions {
  /** Query params to keep verbatim. Everything else becomes `[REDACTED]`. */
  allow?: string[];
}

function isRecord(value: JsonValue | undefined): value is { [key: string]: JsonValue } {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function queryAllowlist(options: QueryAllowlistOptions = {}) {
  const allow = new Set(options.allow ?? []);

  return (record: LogRecord): LogRecord => {
    const http = record.http;
    if (!isRecord(http) || typeof http.search !== "string" || http.search === "") {
      return record;
    }

    if (allow.size === 0) {
      const { search: _search, ...rest } = http;
      return { ...record, http: rest };
    }

    let params: URLSearchParams;
    try {
      params = new URLSearchParams(http.search.replace(/^\?/, ""));
    } catch {
      // Unparseable query string — safer to drop it than to pass it through.
      const { search: _search, ...rest } = http;
      return { ...record, http: rest };
    }

    const parts: string[] = [];
    for (const [key, value] of params) {
      parts.push(
        allow.has(key)
          ? `${encodeURIComponent(key)}=${encodeURIComponent(value)}`
          : `${encodeURIComponent(key)}=[REDACTED]`,
      );
    }

    const search = parts.join("&");
    return { ...record, http: { ...http, search: search ? `?${search}` : "" } };
  };
}

/**
 * Per-request enricher factory for middleware and custom wrappers — NOT for global init().
 * Register the returned function inside your request scope, not via init({ enrichers }).
 *
 * @example
 * // inside your middleware/wrapper, before emit:
 * const enrich = requestMetadata({ method: req.method, path: req.path, ip: req.ip });
 * requestLogger.set(enrich({}));
 */
import type { LogRecord } from "@useamplio/amplio";

export interface RequestContext {
  method: string;
  path: string;
  route?: string;
  status?: number;
  ip?: string;
  userAgent?: string;
  requestId?: string;
}

function nonEmpty(value: string | undefined): string | undefined {
  return value !== undefined && value !== "" ? value : undefined;
}

export function requestMetadata(context: RequestContext) {
  return (record: LogRecord): LogRecord => {
    const route = nonEmpty(context.route);
    const ip = nonEmpty(context.ip);
    const userAgent = nonEmpty(context.userAgent);
    const requestId = nonEmpty(context.requestId) ?? record.request_id;

    return {
      ...record,
      ...(requestId !== undefined ? { request_id: requestId } : {}),
      http: {
        method: context.method,
        path: context.path,
        ...(route !== undefined ? { route } : {}),
        ...(context.status !== undefined ? { status: context.status } : {}),
        ...(ip !== undefined ? { ip } : {}),
        ...(userAgent !== undefined ? { user_agent: userAgent } : {}),
      },
    };
  };
}

/**
 * NextAuth (Auth.js v5) → amplio auth events.
 *
 * Wire into your NextAuth config (create-t3-app: src/server/auth/config.ts):
 *
 *   import { amplioNextAuthEvents } from "../../../telemetry/integrations/next-auth";
 *
 *   export const authConfig = {
 *     providers: [...],
 *     events: amplioNextAuthEvents(),
 *   } satisfies NextAuthConfig;
 *
 * These events fire inside the [...nextauth] route handler. Wrap that route
 * with withAmplio so the rows share the request spine's request_id — in a
 * stock create-t3-app layout `amplio init --yes` (or `init --wire`) does it:
 *
 *   // src/app/api/auth/[...nextauth]/route.ts
 *   const { GET: authGet, POST: authPost } = handlers;
 *   export const GET = withAmplio(authGet);
 *   export const POST = withAmplio(authPost);
 *
 * Uses structural types for the NextAuth event messages instead of importing
 * from next-auth (its v5 type exports are still beta-unstable).
 */
import { logger } from "../logger";
import { AuthUserSignedIn } from "../events/auth/user-signed-in";
import { AuthUserSignedUp } from "../events/auth/user-signed-up";

type NextAuthUser = {
  id?: string;
  email?: string | null;
};

type NextAuthAccount = {
  provider?: string;
  type?: string;
} | null;

export type NextAuthSignInMessage = {
  user: NextAuthUser;
  account?: NextAuthAccount;
  isNewUser?: boolean;
};

export type NextAuthCreateUserMessage = {
  user: NextAuthUser;
};

type SignInMethod = "password" | "oauth" | "magic_link" | "sso";

function signInMethod(account: NextAuthAccount | undefined): SignInMethod {
  switch (account?.type) {
    case "credentials":
      return "password";
    case "email":
      return "magic_link";
    default:
      // oidc / oauth / webauthn all reach the app via a provider flow.
      return "oauth";
  }
}

function userFields(user: NextAuthUser): { id: string; email?: string } | null {
  if (!user.id) {
    return null;
  }
  return { id: user.id, ...(user.email ? { email: user.email } : {}) };
}

// `createUser` (adapter created a user row) is the reliable "signed up"
// signal — `isNewUser` on signIn is not set for database-session credential
// flows. createUser has no account, though, so it cannot name the signup
// method; instead of emitting a half-empty row here we mark the id and let
// the signIn event (which fires right after, with the account) emit
// auth.user.signed_up exactly once with the real method. Bounded so a
// long-lived process never grows it past ~1000 ids.
const newlyCreatedUserIds = new Set<string>();
const NEWLY_CREATED_CAP = 1000;

export function trackNextAuthCreateUser(message: NextAuthCreateUserMessage): void {
  const user = userFields(message.user);
  if (!user) {
    return;
  }
  if (newlyCreatedUserIds.size >= NEWLY_CREATED_CAP) {
    newlyCreatedUserIds.clear();
  }
  newlyCreatedUserIds.add(user.id);
}

export function trackNextAuthSignIn(message: NextAuthSignInMessage) {
  const user = userFields(message.user);
  if (!user) {
    return null;
  }

  // NextAuth fires one signIn event for both flows; isNewUser (or a
  // createUser event seen just before) distinguishes a first-time
  // registration. Emit signed_up as an extra row so both funnels stay
  // queryable on their own event name.
  const isNewUser = message.isNewUser === true || newlyCreatedUserIds.has(user.id);
  newlyCreatedUserIds.delete(user.id);
  if (isNewUser) {
    logger
      .event(AuthUserSignedUp)
      .set({
        user,
        signup: {
          method: message.account?.type === "credentials" ? "email" : "oauth",
        },
      })
      .emit();
  }

  return logger
    .event(AuthUserSignedIn)
    .set({
      user,
      session: { method: signInMethod(message.account) },
    })
    .emit();
}

/**
 * Drop-in `events` object for NextAuth(config). Inside a withAmplio-wrapped
 * route these rows correlate with the http.request spine via request_id;
 * outside one they still emit as standalone rows.
 *
 * Covered: signIn (auth.user.signed_in) and createUser + signIn
 * (auth.user.signed_up — reliable even when isNewUser is not set, e.g.
 * database-session credential flows).
 *
 * Not covered by default — this file is open code, extend it in place:
 *
 *   signOut: NextAuth's message shape depends on session strategy
 *   ({ token } for JWT, { session } for database). Scaffold an event with
 *   `amplio add event auth.user.signed_out`, then add:
 *
 *     signOut: (message: { token?: { sub?: string } | null }) => {
 *       const id = message.token?.sub;
 *       if (id) {
 *         logger.event(AuthUserSignedOut).set({ user: { id } }).emit();
 *       }
 *     },
 *
 *   linkAccount: fires when an OAuth account is linked to an existing user
 *   (message: { user, account }). Scaffold `amplio add event
 *   auth.account.linked` and emit `{ user, account: { provider } }` the same
 *   way.
 */
export function amplioNextAuthEvents() {
  return {
    createUser: (message: NextAuthCreateUserMessage) => {
      trackNextAuthCreateUser(message);
    },
    signIn: (message: NextAuthSignInMessage) => {
      trackNextAuthSignIn(message);
    },
  };
}

import type { BetterAuthPlugin } from "better-auth";
import { createAuthMiddleware } from "better-auth/api";
import { getAccountCookie } from "better-auth/cookies";
import { logger } from "../logger";
import { AuthUserSignedIn } from "../events/auth/user-signed-in";
import { AuthUserSignedUp } from "../events/auth/user-signed-up";

type AuthHookContext = Parameters<Parameters<typeof createAuthMiddleware>[0]>[0];

export function trackBetterAuthSignUp(input: {
  user: { id: string; email: string };
  method: "email" | "oauth" | "invite";
  referrer?: string;
}) {
  return logger
    .event(AuthUserSignedUp)
    .set({
      user: input.user,
      signup: {
        method: input.method,
        ...(input.referrer ? { referrer: input.referrer } : {}),
      },
    })
    .emit();
}

export function trackBetterAuthSignIn(input: {
  user: { id: string; email: string };
  session: { id: string; method: "password" | "oauth" | "magic_link" | "sso"; mfa?: boolean };
}) {
  return logger
    .event(AuthUserSignedIn)
    .set({
      user: input.user,
      session: input.session,
    })
    .emit();
}

function readBody(ctx: AuthHookContext): Record<string, unknown> {
  const body = ctx.body;
  return body && typeof body === "object" ? (body as Record<string, unknown>) : {};
}

function readUser(ctx: AuthHookContext): { id: string; email: string } | null {
  const user = ctx.context.newSession?.user;
  if (!user?.id || !user.email) {
    return null;
  }
  return { id: user.id, email: user.email };
}

function readReferrer(ctx: AuthHookContext): string | undefined {
  const body = readBody(ctx);
  const referrer = typeof body.referrer === "string" ? body.referrer : undefined;
  const callbackURL = typeof body.callbackURL === "string" ? body.callbackURL : undefined;
  return referrer ?? callbackURL;
}

function hasInvitationId(ctx: AuthHookContext): boolean {
  const body = readBody(ctx);
  return typeof body.invitationId === "string" && body.invitationId.length > 0;
}

function isSocialRegistration(ctx: AuthHookContext): boolean {
  const returned = ctx.context.returned;
  if (returned && typeof returned === "object" && "isRegister" in returned) {
    return Boolean((returned as { isRegister?: boolean }).isRegister);
  }
  return false;
}

function readMfa(ctx: AuthHookContext): boolean | undefined {
  const body = readBody(ctx);
  if (typeof body.mfa === "boolean") {
    return body.mfa;
  }
  const session = ctx.context.newSession?.session as { mfa?: boolean } | undefined;
  return session?.mfa;
}

async function readOAuthProvider(ctx: AuthHookContext): Promise<string | undefined> {
  const params = ctx.params as { id?: string } | undefined;
  if (typeof params?.id === "string") {
    return params.id;
  }
  try {
    const account = await getAccountCookie(ctx);
    return account?.providerId;
  } catch {
    return undefined;
  }
}

function trackSignUpFromContext(ctx: AuthHookContext, method: "email" | "oauth" | "invite") {
  const user = readUser(ctx);
  if (!user) {
    return;
  }
  const referrer = readReferrer(ctx);
  trackBetterAuthSignUp({
    user,
    method,
    ...(referrer !== undefined ? { referrer } : {}),
  });
}

function trackSignInFromContext(
  ctx: AuthHookContext,
  method: "password" | "oauth" | "magic_link" | "sso",
) {
  const user = readUser(ctx);
  const session = ctx.context.newSession?.session;
  if (!user || !session?.id) {
    return;
  }
  const mfa = readMfa(ctx);
  trackBetterAuthSignIn({
    user,
    session: {
      id: session.id,
      method,
      ...(mfa !== undefined ? { mfa } : {}),
    },
  });
}

export function createBetterAuthAmplioPlugin(): BetterAuthPlugin {
  return {
    id: "amplio",
    hooks: {
      after: [
        {
          matcher: (ctx) => ctx.path === "/sign-up/email" && !!ctx.context.newSession?.user,
          handler: createAuthMiddleware(async (ctx) => {
            trackSignUpFromContext(ctx, hasInvitationId(ctx) ? "invite" : "email");
          }),
        },
        {
          matcher: (ctx) =>
            (ctx.path === "/organization/signup-with-invitation" ||
              ctx.path.endsWith("/signup-with-invitation")) &&
            !!ctx.context.newSession?.user,
          handler: createAuthMiddleware(async (ctx) => {
            trackSignUpFromContext(ctx, "invite");
          }),
        },
        {
          matcher: (ctx) =>
            ctx.path.startsWith("/callback/") &&
            !!ctx.context.newSession?.user &&
            isSocialRegistration(ctx),
          handler: createAuthMiddleware(async (ctx) => {
            await readOAuthProvider(ctx);
            trackSignUpFromContext(ctx, hasInvitationId(ctx) ? "invite" : "oauth");
          }),
        },
        {
          matcher: (ctx) => ctx.path === "/sign-in/email" && !!ctx.context.newSession?.user,
          handler: createAuthMiddleware(async (ctx) => {
            trackSignInFromContext(ctx, "password");
          }),
        },
        {
          matcher: (ctx) =>
            ctx.path.startsWith("/callback/") &&
            !!ctx.context.newSession?.user &&
            !isSocialRegistration(ctx),
          handler: createAuthMiddleware(async (ctx) => {
            await readOAuthProvider(ctx);
            trackSignInFromContext(ctx, "oauth");
          }),
        },
        {
          matcher: (ctx) => ctx.path === "/magic-link/verify" && !!ctx.context.newSession?.user,
          handler: createAuthMiddleware(async (ctx) => {
            trackSignInFromContext(ctx, "magic_link");
          }),
        },
        {
          matcher: (ctx) =>
            (ctx.path === "/sign-in/sso" ||
              ctx.path.startsWith("/sso/callback") ||
              ctx.path.startsWith("/sso/saml2/")) &&
            !!ctx.context.newSession?.user,
          handler: createAuthMiddleware(async (ctx) => {
            trackSignInFromContext(ctx, "sso");
          }),
        },
      ],
    },
  };
}

import type { WebhookEvent } from "@clerk/backend/webhooks";
import { logger } from "../logger";
import { AuthUserSignedIn } from "../events/auth/user-signed-in";
import { AuthUserSignedUp } from "../events/auth/user-signed-up";

export type ClerkWebhookEvent = WebhookEvent;

type ClerkUserPayload = {
  id: string;
  primary_email_address_id?: string | null;
  email_addresses?: Array<{ id: string; email_address: string }>;
  external_accounts?: Array<{ provider: string }>;
  enterprise_accounts?: Array<{ provider: string }>;
  password_enabled?: boolean;
  two_factor_enabled?: boolean;
  public_metadata?: Record<string, unknown> | null;
  unsafe_metadata?: Record<string, unknown> | null;
  private_metadata?: Record<string, unknown> | null;
};

type ClerkSessionPayload = {
  id: string;
  user_id: string;
  user: ClerkUserPayload | null;
};

export function trackClerkUserCreated(input: {
  user: { id: string; email: string };
  method: "email" | "oauth" | "invite";
  referrer?: string;
}) {
  return logger
    .event(AuthUserSignedUp)
    .set({
      user: input.user,
      signup: {
        method: input.method,
        ...(input.referrer ? { referrer: input.referrer } : {}),
      },
    })
    .emit();
}

export function trackClerkSessionCreated(input: {
  user: { id: string; email?: string };
  session: { id: string; method: "password" | "oauth" | "magic_link" | "sso"; mfa?: boolean };
}) {
  return logger
    .event(AuthUserSignedIn)
    .set({
      user: input.user,
      session: input.session,
    })
    .emit();
}

function clerkPrimaryEmail(user: ClerkUserPayload): string | undefined {
  const addresses = user.email_addresses ?? [];
  if (addresses.length === 0) {
    return undefined;
  }
  const primary = user.primary_email_address_id
    ? addresses.find((address) => address.id === user.primary_email_address_id)
    : addresses[0];
  return primary?.email_address;
}

function metadataReferrer(user: ClerkUserPayload): string | undefined {
  for (const metadata of [user.public_metadata, user.unsafe_metadata, user.private_metadata]) {
    if (!metadata || typeof metadata !== "object") {
      continue;
    }
    const referrer = metadata.referrer ?? metadata.referral;
    if (typeof referrer === "string" && referrer.length > 0) {
      return referrer;
    }
  }
  return undefined;
}

function metadataIndicatesInvite(user: ClerkUserPayload): boolean {
  for (const metadata of [user.public_metadata, user.unsafe_metadata, user.private_metadata]) {
    if (!metadata || typeof metadata !== "object") {
      continue;
    }
    if ("invitation_id" in metadata || "invite" in metadata || "invitationId" in metadata) {
      return true;
    }
  }
  return false;
}

function inferClerkSignUpMethod(user: ClerkUserPayload): "email" | "oauth" | "invite" {
  if (metadataIndicatesInvite(user)) {
    return "invite";
  }
  if ((user.external_accounts?.length ?? 0) > 0) {
    return "oauth";
  }
  return "email";
}

function inferClerkSignInMethod(user: ClerkUserPayload): "password" | "oauth" | "magic_link" | "sso" {
  if ((user.enterprise_accounts?.length ?? 0) > 0) {
    return "sso";
  }
  if ((user.external_accounts?.length ?? 0) > 0) {
    return "oauth";
  }
  if (user.password_enabled === false) {
    return "magic_link";
  }
  return "password";
}

function mapClerkUserCreated(data: ClerkUserPayload) {
  const email = clerkPrimaryEmail(data);
  if (!email) {
    return undefined;
  }
  const referrer = metadataReferrer(data);
  return trackClerkUserCreated({
    user: { id: data.id, email },
    method: inferClerkSignUpMethod(data),
    ...(referrer ? { referrer } : {}),
  });
}

function mapClerkSessionCreated(data: ClerkSessionPayload) {
  const user = data.user;
  const userId = user?.id ?? data.user_id;
  if (!userId) {
    return undefined;
  }
  const email = user ? clerkPrimaryEmail(user) : undefined;
  const signInMethod = user ? inferClerkSignInMethod(user) : "password";
  return trackClerkSessionCreated({
    user: {
      id: userId,
      ...(email ? { email } : {}),
    },
    session: {
      id: data.id,
      method: signInMethod,
      ...(user?.two_factor_enabled ? { mfa: true } : {}),
    },
  });
}

export function handleClerkWebhook(event: ClerkWebhookEvent) {
  switch (event.type) {
    case "user.created":
      return mapClerkUserCreated(event.data);
    case "session.created":
      return mapClerkSessionCreated(event.data);
    default:
      return undefined;
  }
}

import { logger } from "../logger";
import { EmailSent } from "../events/email/sent";

type ResendEmailEventData = {
  email_id: string;
  to: string[];
  subject: string;
  tags?: Record<string, string> | Array<{ name: string; value: string }>;
  template_id?: string;
};

export type ResendWebhookEvent = {
  type: "email.sent" | "email.delivered" | "email.bounced" | "email.complained";
  created_at?: string;
  data: ResendEmailEventData;
};

export function trackResendEmail(input: {
  message: { id: string; to: string; subject: string };
  template: string;
  status: "queued" | "sent" | "failed";
}) {
  return logger
    .event(EmailSent)
    .set({
      email: {
        id: input.message.id,
        template: input.template,
        to: input.message.to,
        subject: input.message.subject,
      },
      delivery: {
        provider: "resend",
        status: input.status,
      },
    })
    .emit();
}

function tagValue(
  tags: ResendEmailEventData["tags"],
  name: string,
): string | undefined {
  if (!tags) {
    return undefined;
  }
  if (Array.isArray(tags)) {
    return tags.find((entry) => entry.name === name)?.value;
  }
  return tags[name];
}

function templateFromTags(
  tags: ResendEmailEventData["tags"],
  templateId?: string,
): string {
  const tagged =
    tagValue(tags, "template") ??
    tagValue(tags, "category") ??
    tagValue(tags, "template_id") ??
    tagValue(tags, "templateId");
  if (tagged) {
    return tagged;
  }
  return templateId ?? "unknown";
}

function resendDeliveryStatus(
  type: ResendWebhookEvent["type"],
): "queued" | "sent" | "failed" {
  switch (type) {
    case "email.sent":
    case "email.delivered":
      return "sent";
    case "email.bounced":
    case "email.complained":
      return "failed";
    default:
      return "queued";
  }
}

export function handleResendWebhook(event: ResendWebhookEvent) {
  switch (event.type) {
    case "email.sent":
    case "email.delivered":
    case "email.bounced":
    case "email.complained": {
      const to = event.data.to[0];
      if (!to) {
        return undefined;
      }
      return trackResendEmail({
        message: {
          id: event.data.email_id,
          to,
          subject: event.data.subject,
        },
        template: templateFromTags(event.data.tags, event.data.template_id),
        status: resendDeliveryStatus(event.type),
      });
    }
    default:
      return undefined;
  }
}

import { logger } from "../logger";
import { PaymentOrderPaid } from "../events/payment/order-paid";

type PolarOrderData = {
  id: string;
  checkout_id?: string | null;
  checkoutId?: string | null;
  total_amount?: number;
  totalAmount?: number;
  currency: string;
  customer?: {
    id: string;
    email?: string | null;
  };
  customer_id?: string;
  customerId?: string;
};

type PolarCheckoutData = {
  id: string;
  status: string;
  total_amount?: number;
  totalAmount?: number;
  currency: string;
  customer_id?: string | null;
  customerId?: string | null;
  customer_email?: string | null;
  customerEmail?: string | null;
};

export type PolarWebhookEvent =
  | { type: "order.paid"; data: PolarOrderData }
  | { type: "checkout.updated"; data: PolarCheckoutData };

export function trackPolarOrderPaid(input: {
  checkout: { id: string; amount: number; currency: string };
  customer: { id: string; email?: string };
  method?: "card" | "bank" | "wallet" | "other";
}) {
  return logger
    .event(PaymentOrderPaid)
    .set({
      order: {
        id: input.checkout.id,
        currency: input.checkout.currency.toUpperCase(),
        amount_cents: input.checkout.amount,
      },
      customer: {
        id: input.customer.id,
        ...(input.customer.email ? { email: input.customer.email } : {}),
      },
      payment: {
        provider: "polar",
        ...(input.method ? { method: input.method } : {}),
      },
    })
    .emit();
}

function readAmount(data: { total_amount?: number; totalAmount?: number }): number {
  return data.totalAmount ?? data.total_amount ?? 0;
}

function mapPolarOrderPaid(data: PolarOrderData) {
  const customerId = data.customer?.id ?? data.customerId ?? data.customer_id;
  if (!customerId) {
    return undefined;
  }
  const checkoutId = data.checkoutId ?? data.checkout_id ?? data.id;
  return trackPolarOrderPaid({
    checkout: {
      id: checkoutId,
      amount: readAmount(data),
      currency: data.currency,
    },
    customer: {
      id: customerId,
      ...(data.customer?.email ? { email: data.customer.email } : {}),
    },
  });
}

function mapPolarCheckoutPaid(data: PolarCheckoutData) {
  const customerId = data.customerId ?? data.customer_id;
  if (!customerId) {
    return undefined;
  }
  const customerEmail = data.customerEmail ?? data.customer_email;
  return trackPolarOrderPaid({
    checkout: {
      id: data.id,
      amount: readAmount(data),
      currency: data.currency,
    },
    customer: {
      id: customerId,
      ...(customerEmail ? { email: customerEmail } : {}),
    },
  });
}

export function handlePolarWebhook(event: PolarWebhookEvent) {
  switch (event.type) {
    case "order.paid":
      return mapPolarOrderPaid(event.data);
    case "checkout.updated":
      if (event.data.status !== "paid") {
        return undefined;
      }
      return mapPolarCheckoutPaid(event.data);
    default:
      return undefined;
  }
}
